package com.cretas.aims.blueprint.draftentry;
import com.cretas.aims.repository.supplierreceiving.SupplierReceivingPolicyDraftRepository;
import com.cretas.aims.service.contractmaterialdraft.ContractMaterialPolicyDraftCommand;
import com.cretas.aims.service.contractmaterialdraft.ContractMaterialPolicyDraftModels.*; import com.cretas.aims.service.supplierreceivingdraft.SupplierReceivingPolicyDraftModels.MaterialRefType;
import org.springframework.stereotype.Component; import java.util.*;
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name = "cretas.platform.factory-assembly.enabled", havingValue = "true", matchIfMissing = false)
@Component public class ContractMaterialDraftProposer implements CapabilityDraftProposer {
 private static final String WHY="蓝图没有客户范围、物料归属、隔离、结算和证据的完整事实";
 private static <E extends Enum<E>> List<Option> opts(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(e->new Option(e.name(),e.name())).toList();} private static <E extends Enum<E>> String ec(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(Enum::name).collect(java.util.stream.Collectors.joining("、"))+" 之一";}
 private static List<RequiredInput> fields(){return List.of(RequiredInput.text("customerScopeCode","客户范围",WHY,"最长 64 位",64),RequiredInput.text("supplierMaterial.supplierId","供应商",WHY,"最长 191 位",191),RequiredInput.oneOf("supplierMaterial.materialRefType","物料类型",WHY,ec(MaterialRefType.class),opts(MaterialRefType.class)),RequiredInput.text("supplierMaterial.materialRefId","物料标识",WHY,"最长 191 位",191),RequiredInput.oneOf("ownershipType","归属类型",WHY,ec(OwnershipType.class),opts(OwnershipType.class)),RequiredInput.oneOf("segregationRequirement","隔离要求",WHY,ec(SegregationRequirement.class),opts(SegregationRequirement.class)),RequiredInput.oneOf("issuancePolicy","领用政策",WHY,ec(IssuancePolicy.class),opts(IssuancePolicy.class)),RequiredInput.oneOf("returnPolicy","退还政策",WHY,ec(ReturnPolicy.class),opts(ReturnPolicy.class)),RequiredInput.oneOf("settlementPolicy","结算政策",WHY,ec(SettlementPolicy.class),opts(SettlementPolicy.class)),RequiredInput.decimal("residualTolerancePercent","残余容差",WHY,"0–100",java.math.BigDecimal.ZERO,java.math.BigDecimal.valueOf(100)),RequiredInput.integer("retentionDays","保留天数",WHY,"0–3650",0,3650),RequiredInput.oneOf("responsibleRole","责任角色",WHY,ec(ResponsibleRole.class),opts(ResponsibleRole.class)),RequiredInput.values("requiredEvidence","要求证据",WHY,"至少 1 项","证据",1,10,RequiredInput.oneOf("evidence","证据",WHY,ec(EvidenceType.class),opts(EvidenceType.class))),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));}
 private final SupplierReceivingPolicyDraftRepository supplierReceiving; public ContractMaterialDraftProposer(SupplierReceivingPolicyDraftRepository supplierReceiving){this.supplierReceiving=supplierReceiving;} public String capabilityId(){return ContractMaterialPolicyDraftCommand.CAPABILITY_ID;}
 public Proposed propose(Source s){var row=UpstreamDraftPins.latestSupplierReceiving(supplierReceiving,s).orElse(null);if(row==null)return Proposed.blocked("UPSTREAM_MISSING","客供料策略必须绑定本蓝图同一版本的供应商收货草稿，当前没有可验证的上游草稿","先写供应商收货草稿");var req=new DraftRequest(s.factoryId(),s.blueprint().getId(),s.blueprint().getVersion(),s.sourceDigest(),new SupplierReceivingPin(row.getId(),row.getDesiredDigest()),List.of(),null,null,0L);return Proposed.single(capabilityId(),"客供料策略",req,List.of(RequiredInput.list("policies","客供料策略",WHY,"至少 1 条，最多 200 条，每条字段均须填写","策略",1,200,fields())),List.of(new Evidence("supplierReceiving",row.getId()+" / "+row.getDesiredDigest())));}
}

